import Foundation

private typealias E = EvidenceSeed

/// Four more general follow-ups: stolen goods in a truck bed, a keyed car, a refusal to leave a library, and a pickup line.
extension FollowUpCases {
    static let batchBR: [CaseTemplate] = [stolenGenerator, keyedCarParking, libraryClosing, schoolPickupLine]

    static let stolenGenerator = SmallCases.make(
        key: "story.followup.stolenGenerator",
        category: .property,
        headlines: ["Stolen Generator Found in Truck Bed After Traffic Stop", "Buyer Says Generator Came From a Stranger"],
        law: "possStolen",
        spec: "Possessed stolen goods, a portable generator valued at $850, knowing or having reason to know it was stolen, on {DATE}.",
        ages: 21...58,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy stopped {D}'s truck at 9:15 p.m. on {DATE} for a broken tag light. A portable generator sat in the bed under a tarp, and a serial number check matched one reported stolen from a job site five days earlier. {DL} says {D.he} bought it that afternoon for $150 from a man in a parking lot.",
        state: [E(.physical, 3, "Generator", "A portable generator with its serial number matching a theft report from five days earlier."),
                E(.document, 3, "Theft Report", "A contractor reported the generator stolen from a job site; it is valued at $850."),
                E(.video, 2, "Body Camera", "{D} says the generator was bought that afternoon for $150.")],
        defense: [E(.statement, 1, "Bought It", "{DL} says {D.he} bought it from a stranger and did not know it was stolen.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I'm a sheriff's deputy, and I make traffic stops in the evening.\""), .direct("Why did you stop {DL}?", "\"A tag light was broken on {D.his} truck, and it was about nine-fifteen at night.\""), .direct("What did you see in the bed?", "\"A portable generator under a tarp, with a rope holding it down.\""), .direct("What did the serial number show?", "\"That the generator was reported stolen from a job site five days earlier.\""), .direct("What was it worth?", "\"About eight hundred fifty dollars, according to the owner's report.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} bought it that afternoon for a hundred fifty dollars from a man in a parking lot.\""), .cross("{DL} had no receipt?", "\"No, {D.he} had no receipt, and {D.he} said it was a cash deal in a lot.\""), .cross("A hundred fifty dollars is low for a generator?", "\"It is a very low price for a generator, and I told {D.him} so at the stop.\""), .cross("{DL} gave a description of the seller?", "\"A vague one, with no name and no plate number, so we have little to go on.\""), .cross("{DL} was cooperative?", "\"Yes, {D.he} was cooperative, and {D.he} let me look under the tarp at once.\""), .cross("The owner got the generator back?", "\"Yes, the owner got the generator back, after the serial number was confirmed.\"")],
        theory: ("{D} had a stolen generator and should have known.", "{D} bought a generator without knowing."),
        allocution: "\"I bought that generator that afternoon from a man in a parking lot for a very low price, and I did not know it was stolen. I should have asked more questions about where it came from. I'm sorry to the people who lost it at a job site, and I'll hand it over and help the deputies.\"",
        truths: ("{DL} was told the generator was 'from a job' when {D.he} bought it.", "The seller approached {DL} at a hardware store lot and showed a work order."),
        defendant: [.direct("Did you know the generator was stolen?", "\"No. I bought it that afternoon from a man in a parking lot, and I thought it was a good deal.\""), .direct("What did you pay?", "\"A hundred fifty dollars, in cash. I knew it was cheap, but he said he was moving.\""), .direct("Did you ask for a receipt?", "\"No. I should have. I didn't think he'd lie to me.\""), .direct("Why did you cover it with a tarp?", "\"To keep the rain off. I didn't think anything of it.\""), .direct("What did you do when the deputy found it?", "\"I told him how I got it, and I gave him my description of the man.\""), .direct("What would you tell the owner?", "\"I'm sorry for your loss. I didn't know it was stolen, and I'm glad you got it back.\""), .cross("You've been convicted of possessing stolen property before, haven't you?", "\"Yes, and I told the court I'd never buy from strangers. I did.\""), .cross("A new generator for a hundred fifty dollars should have raised a flag?", "\"It should have raised a flag, and I made a bad decision that day.\""), .cross("You bought it from a man you can't name?", "\"I can't name him, and I know how that sounds to the court.\""), .cross("You'll look at photos to help find the seller?", "\"Yes, I'll look at photos with the deputy, to try to find the seller.\""), .cross("You'll stop buying from strangers?", "\"Yes, I'll stop buying anything from strangers in parking lots.\"")],
        openings: ("A deputy stopped {D}'s truck at 9:15 p.m. for a broken tag light, and a portable generator sat in the bed under a tarp, and a serial number check matched one reported stolen from a job site five days earlier, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} bought the generator that afternoon for $150 from a man, and did not know it was stolen. {D} paid cash and kept it in plain view under a tarp."),
        closings: ("The serial number matches a generator stolen five days earlier, it was under a tarp in {D}'s truck, and having faced {PRIOR} before, {DL} understood exactly what a $150 generator means.", "A buyer who pays cash from a man cannot know the serial's history. The State must prove {D} knew the generator was stolen."),
        timeline: [(-5, "The generator is stolen from the job site."), (0, "9:15 p.m.: the stop."), (0, "9:30 p.m.: the serial number check."), (1, "The contractor confirms the theft report.")],
        identified: "Stopped at the scene.",
        notDone: ["The seller was never identified."],
        mood: .indifferent)

    static let keyedCarParking = SmallCases.make(
        key: "story.followup.keyedCarParking",
        category: .property,
        headlines: ["Car Keyed Along Both Sides in Apartment Lot", "Neighbor Charged After Car Scratched"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a car, causing damage of $1,150, on {DATE}.",
        ages: 20...58,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} found a long scratch down both sides of a parked car at 7 a.m. on {DATE}. A camera on the apartment building shows a person in a gray hooded sweatshirt walking along the car at 1:10 a.m. {D} lives two doors down and had argued with {V} about parking the week before.",
        state: [E(.video, 3, "Building Camera", "A person in a gray hood drags something along the car at 1:10 a.m."),
                E(.document, 2, "Repair Estimate", "$1,150 to repaint the doors and quarter panels on both sides."),
                E(.statement, 2, "{V}", "{V} says {D} threatened to 'fix' the car's parking the week before.")],
        defense: [E(.statement, 1, "Not Me", "{DL} says {D.he} was asleep and the hood proves nothing.")],
        role: "Car owner",
        exam: [.direct("What happened to your car?", "\"I found a long scratch down both sides of my car at seven in the morning, parked outside my apartment.\""), .direct("What was the damage?", "\"Eleven hundred fifty dollars to repaint both doors and the fenders.\""), .direct("What does the building camera show?", "\"A person in a gray hooded sweatshirt walking along my car at ten past one, dragging something along the side.\""), .direct("Who do you suspect?", "\"{DL}, who lives two doors down, and who argued with me about parking the week before.\""), .direct("What was the argument about?", "\"I'd parked in a spot that {D.he} said was {D.his}, and we both said things we shouldn't have.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was asleep and the hood proves nothing.\""), .cross("The face isn't visible?", "\"No, the hood covered the face, and the picture is too dark to tell more.\""), .cross("Many people wear gray hoods?", "\"Yes, many people in the building wear gray hooded sweatshirts like that one.\""), .cross("{DL} lives close by?", "\"Two doors down from me, which is why I noticed the figure walking past.\""), .cross("You've had no other trouble with {DL}?", "\"Just the parking argument the week before, and that was all there was.\""), .cross("{DL} has not apologized?", "\"No, {D.he} hasn't apologized to me, and {D.he} hasn't offered to pay anything.\"")],
        theory: ("{D} keyed {V}'s car over a parking dispute.", "{D} was asleep; a hood is not an identification."),
        allocution: "\"I was asleep at one in the morning, and I did not scratch that car. We argued about parking before, and I'm sorry the argument got heated. I live two doors down, and a gray sweatshirt is not hard to find. I'm sorry for {V}'s damage, and I hope the real person is found.\"",
        truths: ("{DL} owns a gray hooded sweatshirt that matches the one on the video.", "{DL}'s phone was on the home network all night."),
        defendant: [.direct("Did you key the car?", "\"No. I was asleep at one in the morning. I had nothing to do with the scratch.\""), .direct("Do you own a gray hoodie?", "\"Yes, but so do many people. It's a common sweatshirt.\""), .direct("Did you argue with {V} about parking?", "\"Yes, and I said some things I regret. I'd never damage a car over a space.\""), .direct("Who can say you were asleep?", "\"My roommate can say so, because he heard me snoring all that night.\""), .direct("What did you do when the deputy came?", "\"I told {OFF.him} I was asleep, and I let {OFF.him} look at my sweatshirt.\""), .direct("What would you tell {V}?", "\"I'm sorry about your car. It wasn't me, and I hope you find who did it.\""), .cross("You've been charged with damaging a car before, haven't you?", "\"Yes, and I told the court then I'd stay away from trouble for good. I didn't do it this time.\""), .cross("You lived two doors down and argued with the owner the week before?", "\"I did, and I know why that points to me.\""), .cross("Your roommate is not an independent witness?", "\"{V.He} isn't an independent witness, but {V.he}'s honest, and {V.he}'ll tell the truth.\""), .cross("You'll let the deputy search your apartment?", "\"Yes, I'll let the deputy search my apartment and my sweatshirt, today.\""), .cross("You'll stay away from {V}'s car?", "\"Yes, I'll stay away from {V}'s car, and I'll park far from {V.him}.\"")],
        openings: ("{V} found a long scratch down both sides of a parked car at 7 a.m., and a camera on the apartment building shows a person in a gray hooded sweatshirt walking along the car at 1:10 a.m. {D} lives two doors down and had argued with {V} about parking the week before, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} was asleep at 1:10 a.m. and a gray hooded sweatshirt is worn by hundreds of people. A hood hides a face, and no one saw {D} touch the car."),
        closings: ("The camera shows a hooded person walking along the car at 1:10 a.m., {D} lives two doors down, and since {PRIOR}, {DL} could not have missed whose car it was.", "A quarrel a week earlier does not name the person under the hood. The State must prove {D} was the one who scratched the car."),
        timeline: [(-7, "{DL} and {V} argue about the parking spot."), (0, "1:10 a.m.: the hooded figure at the car."), (0, "7 a.m.: {V} finds the damage."), (2, "The building sends its camera footage.")],
        identified: "{DL} lives two doors from the car and argued with {V}.",
        notDone: ["No one examined the sweatshirt {DL} owns."],
        mood: .divided)

    static let libraryClosing = SmallCases.make(
        key: "story.followup.libraryClosing",
        category: .publicOrder,
        headlines: ["Patron Refuses to Leave Library at Closing and Pulls Away From Deputy", "Library Closing Ends in Obstruction Charge"],
        law: "resisting",
        threshold: 5,
        spec: "Willfully resisted, delayed, and obstructed a public officer, a sheriff's deputy, in discharging a duty of the officer's office, on {DATE}.",
        ages: 20...58,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, library staff asked {D} to leave at the 8 p.m. closing on {DATE}. {DL} stayed at a computer, and a deputy arrived at 8:20 p.m. and gave three orders to leave. {DL} said no, then pulled away when the deputy took {D.his} arm.",
        state: [E(.video, 3, "Library Camera", "{D} stays at the computer and pulls away from the deputy at 8:24 p.m."),
                E(.document, 2, "Deputy's Report", "Three orders to leave and a pulled arm."),
                E(.statement, 2, "Librarian", "Asked {DL} to leave twice at 8 p.m.")],
        defense: [E(.statement, 1, "Finishing a Form", "{DL} says {D.he} was finishing a benefits application due that night.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I'm a sheriff's deputy, and I respond to calls at public buildings.\""), .direct("What was the call?", "\"Library staff asked a man to leave at closing, and he wouldn't, so they called us at about eight-fifteen.\""), .direct("What did you do?", "\"I arrived at eight-twenty, and I gave {DL} three orders to leave the building.\""), .direct("What did {DL} do?", "\"{D.He} said no, stayed at the computer, and then pulled away when I took {D.his} arm.\""), .direct("What does the library camera show?", "\"{DL} staying at the computer, and pulling away from me at eight-twenty-four.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was finishing a benefits application due that night.\""), .cross("The application was due that night?", "\"{D.He} said so, and it was a deadline for assistance.\""), .cross("{DL} wasn't violent?", "\"No, {D.he} didn't strike the deputy. {D.He} only pulled away from {D.his} grip.\""), .cross("{DL} left after the arrest?", "\"{D.He} was arrested, yes, after pulling away from me the second time.\""), .cross("The library closed at eight?", "\"Yes, the library closed at eight, and the hours are posted at the door.\""), .cross("{DL} could have come back tomorrow?", "\"{D.He} could have come back tomorrow, but the deadline was midnight that night.\"")],
        theory: ("{D} refused three orders and pulled away.", "{D} was trying to finish an application."),
        allocution: "\"I had a form due that night, and I stayed at the computer past closing because I could not afford to miss the deadline. I should have stopped when the deputy gave the first order. I pulled my arm away out of panic. I'm sorry to the librarians and to the deputy.\"",
        truths: ("{DL} could have finished it on a phone in a few minutes.", "The benefits form was due at midnight."),
        defendant: [.direct("Did you refuse the deputy's orders?", "\"I told {OFF.him} I needed a few more minutes to submit my application. I didn't mean to disobey.\""), .direct("What was the application for?", "\"My benefits. It was due at midnight, and if I missed it, I'd lose my help.\""), .direct("Why didn't you go home and finish?", "\"I don't have a computer or internet at home. The library was my only chance.\""), .direct("Did you resist when the deputy took your arm?", "\"I pulled away because I was afraid I'd lose my place. I didn't mean to resist.\""), .direct("What did you do after?", "\"I went with him, and I didn't fight. I was upset.\""), .direct("What would you tell the deputy and the library?", "\"I'm sorry for not leaving when asked. I should have asked the staff for help.\""), .cross("You've been charged with resisting an officer before, haven't you?", "\"Yes, and I told the court I'd comply. I didn't.\""), .cross("You refused three orders to leave?", "\"I did refuse the deputy's orders, and I regret it now.\""), .cross("You pulled away from the deputy?", "\"I did pull away from the deputy, and I know that's resisting.\""), .cross("You'll use a different place to finish deadlines?", "\"Yes, I'll ask the library for help earlier in the day.\""), .cross("You'll apologize to the library staff?", "\"Yes, I'll apologize to the library staff, and finish my forms earlier in the day.\"")],
        openings: ("Library staff asked {D} to leave at the 8 p.m. closing, {D} stayed at a computer, and a deputy arrived at 8:20 p.m. and gave three orders to leave, and {D} said no, then pulled away when the deputy took {D}'s arm, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} was in the middle of finishing a form and did not understand that the order was final. A pull away is a flinch, not a fight."),
        closings: ("Staff asked {D} to leave, a deputy gave three orders, {D} refused each one and pulled away, and after {PRIOR} {DL} understood exactly what those orders meant.", "A person finishing a form at a library is not a criminal, and a flinch is not resistance. The State must prove {D} knew the orders were lawful and defied them."),
        timeline: [(0, "8 p.m.: closing and the first request."), (0, "8:20 p.m.: the deputy arrives."), (0, "8:24 p.m.: the arm is taken and {D} pulls away."), (1, "The library sends its footage.")],
        identified: "Identified at the scene.",
        notDone: ["The benefits agency was never asked about the deadline."],
        mood: .sympathetic)

    static let schoolPickupLine = SmallCases.make(
        key: "story.followup.schoolPickupLine",
        category: .traffic,
        headlines: ["Driver Passes Pickup Line at 40 Past School Crosswalk", "Reckless Driving Charge After Near Miss With Children"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, passing stopped cars at 40 miles per hour in a school pickup zone, on {DATE}.",
        ages: 20...58,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a crossing guard saw {D} pass a line of stopped cars at 40 miles per hour on the shoulder in front of an elementary school at 3:10 p.m. on {DATE}. Children were crossing at the marked crosswalk. {DL} says the line was moving and the guard's flag was not visible.",
        state: [E(.video, 3, "School Camera", "A car passes the stopped line on the shoulder as children enter the crosswalk."),
                E(.statement, 3, "Crossing Guard", "The guard steps back as the car passes within a few feet."),
                E(.document, 2, "Speed Check", "A radar sign records 40 in a 15 zone.")],
        defense: [E(.statement, 1, "Flag Not Visible", "{DL} says the flag was hidden by a bus.")],
        role: "Crossing guard",
        exam: [.direct("What is your job?", "\"I'm a crossing guard at an elementary school, and I direct traffic and watch the crosswalk at pickup time.\""), .direct("What happened that afternoon?", "\"At about ten after three, a car passed a line of stopped cars on the shoulder at high speed, right in front of the school.\""), .direct("How fast was it going?", "\"Around forty miles an hour, in a school zone with a limit of twenty.\""), .direct("Were children crossing?", "\"Yes, several were stepping into the crosswalk, and I was holding my flag up.\""), .direct("What does the school camera show?", "\"A car passing the stopped line on the shoulder as the children enter the crosswalk.\""), .direct("What did {DL} say?", "\"{D.He} said the line was moving and that my flag wasn't visible.\""), .cross("The line of cars was stopped?", "\"Yes, the line of cars was stopped, because I had stopped traffic for the children.\""), .cross("A bus was parked nearby?", "\"Yes, a bus was parked nearby, but it wasn't blocking my flag from the road.\""), .cross("No child was hit?", "\"No child was hit, but one child had to step back onto the curb.\""), .cross("{DL} didn't stop?", "\"{D.He} slowed a little, but {D.he} didn't come to a stop for the children.\""), .cross("{DL} gave a reason?", "\"{D.He} said {D.he} was in a hurry, and had somewhere to be.\"")],
        theory: ("{D} passed a stopped line at 40 as children crossed.", "{D} did not see the guard."),
        allocution: "\"It looked like the line was moving, and the crossing guard's flag was not visible. I should have stayed in line and not used the shoulder. I could have hurt a child, and I'm so sorry. I'll slow down in school zones and always wait my turn.\"",
        truths: ("{DL} had been told by the school to use the side road.", "The bus did block the flag for about three seconds."),
        defendant: [.direct("Did you pass the line of cars?", "\"I did, and I was going too fast. I didn't see the flag because a bus blocked my view.\""), .direct("Why did you use the shoulder?", "\"The line of cars looked like it was moving, and I thought I could get around it.\""), .direct("Did you see the children?", "\"Not until I was close. I braked, but I was still too fast.\""), .direct("Why were you in a hurry?", "\"I was late for an appointment, and I let it make me careless.\""), .direct("What did you do when you saw the guard?", "\"I stopped, and I apologized. I told the guard I hadn't seen the guard step out.\""), .direct("What would you tell the crossing guard and the parents?", "\"I'm sorry for scaring you. I could have hurt a child, and I'll never speed through a school zone again.\""), .cross("You have been cited for speeding in a school zone before, haven't you?", "\"Yes, and I told the court I'd slow down. I didn't.\""), .cross("Forty in a twenty with children crossing is dangerous, isn't it?", "\"It is very dangerous, and I know that, and I'm ashamed.\""), .cross("You passed stopped cars on the shoulder?", "\"I did pass the stopped cars on the shoulder, and I know it was reckless.\""), .cross("You'll take a driving class?", "\"Yes, I'll take a safe-driving class, and I'll finish every session.\""), .cross("You'll avoid the school at pickup time?", "\"Yes, I'll avoid the school at pickup time, and use a different road.\"")],
        openings: ("A crossing guard saw {D} pass a line of stopped cars at 40 miles per hour on the shoulder in front of an elementary school at 3:10 p.m., while children were crossing at the marked crosswalk, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the line was moving and the guard's flag was not visible, and {D} did not see children crossing. {D} meant no danger to any child."),
        closings: ("The guard saw {D} pass stopped cars at 40 miles per hour while children crossed, and with {PRIOR} behind {D.him}, {DL} knew what that crosswalk is at pickup time.", "A moving line and an unseen flag explain a pass better than recklessness does. The State must prove {D} saw the children and drove past them."),
        timeline: [(0, "3:10 p.m.: the car passes the line."), (0, "3:15 p.m.: the guard reports it."), (1, "The school sends its camera footage.")],
        identified: "Identified from the school camera and the radar sign.",
        notDone: ["The bus driver was never interviewed."],
        mood: .wantsConviction)
}
